import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.toList;class Result {public static long stockmax(List<Integer> prices){long profit=0;int max=0;for(int i=prices.size()-1;i>=0;i--){int price=prices.get(i);if(price>max){max=price;}else{profit+= (long)(max - price);} }return profit;}}public class Solution{public static void main(String[] args) throws IOException{BufferedReader bufferedReader=new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter=new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));int t=Integer.parseInt(bufferedReader.readLine().trim());for(int tItr=0;tItr<t;tItr++){int n=Integer.parseInt(bufferedReader.readLine().trim());List<Integer> prices=Stream.of(bufferedReader.readLine().trim().split(" ")).map(Integer::parseInt).collect(toList());long result=Result.stockmax(prices);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();}bufferedReader.close();bufferedWriter.close();}}